            # Update ii to the maximum of current ii and last occurrence of x
            ii = max(ii, last[x])

            # Check if we can start a new segment at index i
            if ii < i:
                p += 1

        # Return 2^p mod MOD
        return pow(2, p + 1, MOD)

class Solution:
    def maximumLength(self, s: str) -> int:
        # Check if string contains only one unique character
        if len(set(s)) == 1:
            return -1

        # Start from the largest possible substring length that could occur thrice
        i = len(s) - 3
        while i >= 0:
            d = {}
            count = 0
            j = i
            while j < len(s):
                # Check single character substring (always special)
                char = s[j]
                if char not in d:
                    d[char] = 0
                d[char] += 1

                # Check if this character appears exactly 3 times
                if d[char] == 3:
                    return 1  # Length of single character substring

                j += 1

            i -= 1

        return -1

